/**
 * Custom Worker entrypoint around the OpenNext handler (same pattern Solmint
 * runs in production):
 *
 *  1. Edge rate limiting for /api/*, using the RL_* bindings. It lives here,
 *     not in Next middleware, because the Worker's own fetch has `env`
 *     directly. Scans spend RPC credits and AI calls bill Workers AI, so both
 *     get their own, tighter buckets. Fails open, and says so in a header.
 *
 *  2. The Watchtower cron: re-scans the watchlist and records alerts.
 *
 * `.open-next/worker.js` is generated by `opennextjs-cloudflare build`, so
 * this file is deployed only after a build (`npm run deploy` builds first).
 */
import openNextHandler from '../.open-next/worker.js';

const CANONICAL_HOST = 'rughawk.xyz';

const RL_BUCKETS = [
  { prefix: '/api/scan', binding: 'RL_SCAN', label: 'scan' },
  { prefix: '/api/shield', binding: 'RL_SCAN', label: 'scan' },
  { prefix: '/api/ai/', binding: 'RL_AI', label: 'ai' },
  { prefix: '/api/rpc', binding: 'RL_RPC', label: 'rpc' },
];
const RL_DEFAULT = { binding: 'RL_API', label: 'api' };
const RL_EXEMPT = ['/api/og/', '/api/cron/', '/api/health', '/api/billing/webhook'];

async function rateLimited(request, env, pathname) {
  if (!pathname.startsWith('/api/') || RL_EXEMPT.some((p) => pathname.startsWith(p))) {
    return { response: null, state: 'exempt' };
  }
  // API-plan calls (Authorization: Bearer rh_live_...) are metered per key by
  // the route; at the edge they share the wider API bucket, keyed by the key
  // itself so one customer's bots never throttle another's.
  const auth = request.headers.get('authorization') ?? '';
  const keyed = /^Bearer\s+rh_live_/i.test(auth);
  const bucket = keyed ? { binding: 'RL_API', label: 'key' } : (RL_BUCKETS.find((b) => pathname.startsWith(b.prefix)) ?? RL_DEFAULT);
  try {
    const limiter = env[bucket.binding];
    if (!limiter || typeof limiter.limit !== 'function') return { response: null, state: `${bucket.label}:nobinding` };
    // cf-connecting-ip is set by Cloudflare and cannot be spoofed at the edge.
    const ip = request.headers.get('cf-connecting-ip') ?? 'unknown';
    const { success } = await limiter.limit({ key: keyed ? `key:${auth.slice(-24)}` : `${bucket.label}:${ip}` });
    if (success) return { response: null, state: `${bucket.label}:ok` };
    return {
      state: `${bucket.label}:blocked`,
      response: new Response(JSON.stringify({ error: 'Rate limit exceeded. Slow down and try again in a minute.' }), {
        status: 429,
        headers: { 'Content-Type': 'application/json', 'Retry-After': '60', 'Cache-Control': 'no-store', 'X-RugHawk-RateLimit': bucket.label },
      }),
    };
  } catch {
    return { response: null, state: `${bucket.label}:error` };
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    // www is an alias: one canonical host for shares, metadata and the origin allowlist.
    if (url.hostname === `www.${CANONICAL_HOST}`) {
      url.hostname = CANONICAL_HOST;
      return Response.redirect(url.toString(), 301);
    }
    const { pathname } = url;
    const rl = await rateLimited(request, env, pathname);
    if (rl.response) return rl.response;
    const response = await openNextHandler.fetch(request, env, ctx);
    if (pathname.startsWith('/api/')) {
      const out = new Response(response.body, response);
      out.headers.set('X-RugHawk-RL', rl.state);
      return out;
    }
    return response;
  },

  async scheduled(controller, env, ctx) {
    const base = env.NEXT_PUBLIC_APP_URL || 'https://rughawk.xyz';
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch(`${base}/api/cron/watch`, {
        method: 'POST',
        headers: { 'x-cron-key': env.CRON_SECRET ?? '' },
      }),
    );
  },
};
